// SPDX-License-Identifier: MIT
pragma solidity ^0.8.9;

contract Election {
    address public admin;
    bool public electionStarted;
    bool public electionEnded;

    struct Candidate {
        uint id;
        string name;
        string description;
        uint voteCount;
    }

    mapping(uint => Candidate) public candidates;
    mapping(address => bool) public hasVoted;

    uint public candidatesCount;

    constructor() {
        admin = msg.sender;
    }

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can perform this action");
        _;
    }

    function startElection() public onlyAdmin {
        require(!electionStarted, "Election already started");
        electionStarted = true;
    }

    function endElection() public onlyAdmin {
        require(electionStarted, "Election not yet started");
        require(!electionEnded, "Election already ended");
        electionEnded = true;
    }

    function addCandidate(string memory _name, string memory _description) public onlyAdmin {
        require(electionStarted == false, "Cannot add candidates after election started");
        candidatesCount++;
        candidates[candidatesCount] = Candidate(candidatesCount, _name, _description, 0);
    }

    function vote(uint _candidateId) public {
        require(electionStarted, "Election has not started yet");
        require(!electionEnded, "Election has ended");
        require(!hasVoted[msg.sender], "You have already voted");
        require(_candidateId > 0 && _candidateId <= candidatesCount, "Invalid candidate");

        hasVoted[msg.sender] = true;
        candidates[_candidateId].voteCount++;
    }

    function getWinner() public view returns (string memory winnerName) {
        require(electionEnded, "Election not yet ended");

        uint maxVotes = 0;
        uint winnerId = 0;

        for (uint i = 1; i <= candidatesCount; i++) {
            if (candidates[i].voteCount > maxVotes) {
                maxVotes = candidates[i].voteCount;
                winnerId = i;
            }
        }

        winnerName = candidates[winnerId].name;
    }
}

